      "inputs": {
        "condition": "$vars.getBellevueWeather1.output.current_weather.temperature >= 15 && $vars.getBellevueWeather1.output.current_weather.weathercode <= 3",
        "trueLabel": "Nice day",
        "falseLabel": "Not ideal"
