        "language": "js",
        "script": "const temp = $vars.getBellevueWeather1.output.current_weather.temperature;\nconst code = $vars.getBellevueWeather1.output.current_weather.weathercode;\nreturn { message: `Yes, it's a nice day in Bellevue! 🌤️ Temperature: ${temp}°C, Weather code: ${code}. Great time to head outside!` };"
